<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('buy_list')}" class="on">模板使用记录</a>					<a href="{pigcms{:U('index')}">返回饭票列表</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Meal_card/buy_list')}" method="get">							<input type="hidden" name="c" value="Meal_card"/>							<input type="hidden" name="a" value="buy_list"/>							筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>用户昵称</option>								<option value="mer_name" <if condition="$_GET['searchtype'] eq 'mer_name'">selected="selected"</if>>商户名称</option>							</select>							<font color="#000">时间筛选5：</font>							<input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onclick="WdatePicker({maxDate:'#F{$dp.$D(\'d4312\')||\'2020-10-01\'}'})"/>			   							<input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onclick="WdatePicker({minDate:'#F{$dp.$D(\'d4311\')}',maxDate:'2020-10-01'})"/>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>							<a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出记录</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th>序号</th>								<th>使用商家</th>								<th>充值用户</th>								<th>充值金额（元）</th>								<th>充值时间</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.order_id}</td>										<td>{pigcms{$vo.mer_name}</td>										<td>{pigcms{$vo.user_name}</td>										<td>{pigcms{$vo.money}</td>										<td>{pigcms{$vo.pay_time|date='Y-m-d H:i:s',###}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="6">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>		<script>		var url = "{pigcms{$config.site_url}"		//var export_url = "{pigcms{:U('User/export')}"		var export_url = "{pigcms{:U('Meal_card/buy_export')}";</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>